#include <cub/block/block_reduce.cuh>
#include <cuda/functional>
#include <cuda/std/functional>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <c10/cuda/CUDAGuard.h>

template <int BlockThreads, bool Broadcast>
__global__ void normalize_counts_kernel(const int *input, float *output, int columns) {
  using reduce_t = cub::BlockReduce<int, BlockThreads>;
  __shared__ typename reduce_t::TempStorage storage;
  __shared__ int sum_slot;
  const auto row = static_cast<std::int64_t>(blockIdx.x) * columns;
  int sum = 0;
  for (int column = threadIdx.x; column < columns; column += BlockThreads)
    sum += input[row + column];
  if constexpr (Broadcast) {
    sum = reduce_t(storage).ReduceBroadcast(sum, cuda::std::plus<>{});
  } else {
    sum = reduce_t(storage).Sum(sum);
    if (threadIdx.x == 0)
      sum_slot = sum;
    __syncthreads();
    sum = sum_slot;
  }
  for (int column = threadIdx.x; column < columns; column += BlockThreads)
    output[row + column] = static_cast<float>(input[row + column]) / sum;
}

template <int BlockThreads>
__global__ void first_thread_kernel(const int *input, int *output) {
  using reduce_t = cub::BlockReduce<int, BlockThreads>;
  __shared__ typename reduce_t::TempStorage storage;
  const int value = input[static_cast<std::int64_t>(blockIdx.x) * BlockThreads + threadIdx.x];
  const int sum = reduce_t(storage).Sum(value);
  __syncthreads();
  const int maximum = reduce_t(storage).Reduce(value, cuda::maximum<>{});
  if (threadIdx.x == 0) {
    output[2 * blockIdx.x] = sum;
    output[2 * blockIdx.x + 1] = maximum;
  }
}

template <int BlockThreads>
void launch(const at::Tensor &input, at::Tensor &output, bool first_thread,
            bool broadcast, cudaStream_t stream) {
  const int columns = static_cast<int>(input.size(-1));
  const auto rows = input.numel() / columns;
  if (first_thread) {
    first_thread_kernel<BlockThreads><<<rows, BlockThreads, 0, stream>>>(
        input.data_ptr<int>(), output.data_ptr<int>());
    return;
  }
#if USE_BROADCAST
  if (broadcast) {
    normalize_counts_kernel<BlockThreads, true><<<rows, BlockThreads, 0, stream>>>(
        input.data_ptr<int>(), output.data_ptr<float>(), columns);
    return;
  }
#endif
  normalize_counts_kernel<BlockThreads, false><<<rows, BlockThreads, 0, stream>>>(
      input.data_ptr<int>(), output.data_ptr<float>(), columns);
}

at::Tensor normalize(const at::Tensor &input, bool first_thread, bool broadcast) {
  TORCH_CHECK(input.is_cuda() && input.scalar_type() == at::kInt && input.is_contiguous(),
              "Expected contiguous CUDA int32 counts with a positive row total");
  TORCH_CHECK(input.dim() >= 2 && input.size(-1) > 0, "Expected nonempty rows");
  const int columns = static_cast<int>(input.size(-1));
  TORCH_CHECK(!first_thread || columns == 32 || columns == 128 || columns == 256 || columns == 512,
              "First-thread control requires one element per thread");
  const c10::cuda::CUDAGuard guard(input.device());
  at::Tensor output = first_thread ? at::empty({input.numel() / columns, 2}, input.options())
                                  : at::empty_like(input, input.options().dtype(at::kFloat));
  const auto stream = at::cuda::getCurrentCUDAStream();
  if (columns <= 32)
    launch<32>(input, output, first_thread, broadcast, stream);
  else if (columns <= 128)
    launch<128>(input, output, first_thread, broadcast, stream);
  else if (columns <= 256)
    launch<256>(input, output, first_thread, broadcast, stream);
  else
    launch<512>(input, output, first_thread, broadcast, stream);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return output;
}

"""Resample whole, uncontaminated APPA/PAAP quartets; retain every result."""

import argparse
import json
import math
import random
import statistics
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("--status", type=Path, nargs="+", required=True)
parser.add_argument("--manifest", type=Path, required=True)
parser.add_argument("--output", type=Path, required=True)
args = parser.parse_args()
manifest = json.loads(args.manifest.read_text())
harnesses = {item["path"]: item["sha256"] for item in manifest["harnesses"]}
common_hashes = {
    value for path, value in harnesses.items() if path.endswith("/common.py")
}
assert len(common_hashes) == 1
quartets = {}
for path in args.status:
    for row in json.loads(path.read_text())["completed"]:
        quartets.setdefault((row["experiment"], row["quartet"]), []).append(row)
results = {}
invalid = []
for (experiment, quartet), workers in sorted(quartets.items()):
    if len(workers) != 4:
        invalid.append(
            {"experiment": experiment, "quartet": quartet, "reason": "incomplete"}
        )
        continue
    valid = all(
        row["exit_code"] == 0
        and not any(o["foreign_selected_gpu"] for o in row["observations"])
        for row in workers
    )
    for row in workers:
        for phase in ["before", "after"]:
            valid &= not any(
                "GPU-8ee84e7d-143f-dd29-1097-85943783e027" in line
                and int(line.split(",")[0]) not in [row["pid"], row["reservation_pid"]]
                for line in row[phase]["apps"].splitlines()
            )
    cases = {}
    for row in workers:
        output = Path(row["command"][row["command"].index("--output") + 1])
        record = json.loads((args.output.parent / output.name).read_text())
        arm = record["arms"][0] if "arms" in record else record
        expected = manifest["artifacts"][experiment][row["arm"]]
        valid &= all(
            arm[key] == expected[key]
            for key in ["source_sha", "source_diff_sha256", "library_sha256"]
        )
        script = Path(row["command"][1])
        valid &= arm["harness_sha256"] == harnesses[str(script)]
        valid &= arm["common_sha256"] in common_hashes
        valid &= arm["pid"] == row["pid"]
        for case in arm["cases"]:
            key = (
                (case["kind"], case["columns"])
                if "columns" in case
                else ("model", case["input_tokens"])
            )
            samples = case["samples_us"] if "samples_us" in case else case["samples_ms"]
            cases.setdefault(key, []).append(
                (row["arm"], statistics.median(samples), case["input_sha256"], case)
            )
    if not valid:
        invalid.append(
            {
                "experiment": experiment,
                "quartet": quartet,
                "reason": "foreign GPU work or artifact mismatch",
            }
        )
        continue
    for key, arms in cases.items():
        assert len(arms) == 4 and len({value[2] for value in arms}) == 1
        output_key = "output_sha256" if "columns" in arms[0][3] else "logits_sha256"
        assert len({value[3][output_key] for value in arms}) == 1
        a = statistics.geometric_mean(value[1] for value in arms if value[0] == "A")
        p = statistics.geometric_mean(value[1] for value in arms if value[0] == "P")
        results.setdefault((experiment, *key), []).append(
            {
                "quartet": quartet,
                "baseline": a,
                "candidate": p,
                "ratio": a / p,
                "baseline_worker_medians": [
                    value[1] for value in arms if value[0] == "A"
                ],
                "candidate_worker_medians": [
                    value[1] for value in arms if value[0] == "P"
                ],
            }
        )
report = {"invalid_quartets": invalid, "cases": [], "protocol": manifest["protocol"]}
lines = [
    "# Independent formal follow-up",
    "",
    "Latency columns are medians of all process medians (µs for consumers, ms for models).",
    "",
    "| Workload | Kind/width | Quartets | A | P | A/P | 95% quartet CI | Result |",
    "| :--- | :--- | ---: | ---: | ---: | ---: | :--- | :--- |",
]
for (experiment, kind, width), groups in sorted(results.items()):
    logs = [math.log(group["ratio"]) for group in groups]
    ratio = math.exp(statistics.mean(logs))
    ci = None
    result = "incomplete"
    if len(groups) == 8:
        rng = random.Random(11504)
        boot = sorted(
            math.exp(statistics.mean(rng.choices(logs, k=8))) for _ in range(10000)
        )
        ci = [boot[249], boot[9749]]
        if kind == "first-thread":
            result = (
                "within default bound" if ci[0] >= 0.99 else "default bound not met"
            )
        else:
            result = "stable >1% gain" if ci[0] > 1.01 else "no stable >1% gain"
    row = {
        "experiment": experiment,
        "kind": kind,
        "width": width,
        "ratio": ratio,
        "ci95": ci,
        "quartets": groups,
        "result": result,
        "baseline_latency": statistics.median(
            value for group in groups for value in group["baseline_worker_medians"]
        ),
        "candidate_latency": statistics.median(
            value for group in groups for value in group["candidate_worker_medians"]
        ),
    }
    report["cases"].append(row)
    interval = f"{ci[0]:.4f}–{ci[1]:.4f}" if ci else "—"
    lines.append(
        f"| {experiment} | {kind}/{width} | {len(groups)} | {row['baseline_latency']:.3f} | {row['candidate_latency']:.3f} | {ratio:.4f}× | {interval} | {result} |"
    )
args.output.with_suffix(".json").write_text(json.dumps(report, indent=2) + "\n")
args.output.with_suffix(".md").write_text("\n".join(lines) + "\n")
print(len(report["cases"]), "cases;", len(invalid), "invalid quartets retained")
